# source forge/scripts/sandbox-env.sh              # set up the environment
# source forge/scripts/sandbox-env.sh --make       # also recompile stale Forge modules

# Note: this file was generated by Claude Opus as part of an effort to enable running 
# Forge's test suite in an `sbx` sandbox. 

if ! (return 0 2>/dev/null); then
  echo "sandbox-env.sh must be sourced: source $0" >&2
  exit 1
fi

if [ -z "${TMPDIR:-}" ] && [ -z "${FORGE_SANDBOX_DIR:-}" ]; then
  echo "sandbox-env.sh: set TMPDIR or FORGE_SANDBOX_DIR to a writable directory." >&2
  return 1
fi

export FORGE_SANDBOX_DIR="${FORGE_SANDBOX_DIR:-$TMPDIR/forge-sandbox}"

# Record the original cache and add-on directory once, before HOME changes.
export FORGE_SANDBOX_ORIG_COMPILED="${FORGE_SANDBOX_ORIG_COMPILED:-$PLTCOMPILEDROOTS}"
if [ -z "${PLTADDONDIR:-}" ]; then
  PLTADDONDIR="$(racket -e '(display (find-system-path (quote addon-dir)))')"
  export PLTADDONDIR
fi

mkdir -p "$FORGE_SANDBOX_DIR/home" "$FORGE_SANDBOX_DIR/javatmp"
if [ ! -d "$FORGE_SANDBOX_DIR/compiled" ]; then
  if [ -n "$FORGE_SANDBOX_ORIG_COMPILED" ] && [ -d "$FORGE_SANDBOX_ORIG_COMPILED" ]; then
    cp -a "$FORGE_SANDBOX_ORIG_COMPILED" "$FORGE_SANDBOX_DIR/compiled"
  else
    mkdir -p "$FORGE_SANDBOX_DIR/compiled"
  fi
fi

export PLTCOMPILEDROOTS="$FORGE_SANDBOX_DIR/compiled"
export HOME="$FORGE_SANDBOX_DIR/home"
case " ${JAVA_TOOL_OPTIONS:-} " in
  *" -Djava.io.tmpdir=$FORGE_SANDBOX_DIR/javatmp "*) ;;
  *) export JAVA_TOOL_OPTIONS="${JAVA_TOOL_OPTIONS:+$JAVA_TOOL_OPTIONS }-Djava.io.tmpdir=$FORGE_SANDBOX_DIR/javatmp" ;;
esac

if [ "${1:-}" = "--make" ]; then
  (
    cd "$(dirname "${BASH_SOURCE[0]}")/.." &&
    find . -name "*.rkt" -not -path "./tests/*" -not -path "*/compiled/*" -print0 |
      xargs -0 raco make -j 6
  )
fi
